insert into public.onboarding_criteria (criterion_id, version, name, activity, requirements) values
  ('OB01', '2026-10-09', 'Chào hỏi và thiết lập kết nối', 1, '["Chào cả phụ huynh và học sinh.", "Xác nhận âm thanh, hình ảnh và điều kiện tương tác.", "Gọi đúng tên người tham gia.", "Có lời hỏi thăm hoặc small talk phù hợp để tạo không khí thân thiện."]'::jsonb),
  ('OB02', '2026-10-09', 'Giới thiệu Mentor và xây dựng sự tin tưởng', 1, '["Giới thiệu tên, vai trò.", "Chia sẻ một thông tin cá nhân hoặc kinh nghiệm phù hợp nhằm tạo kết nối và thể hiện năng lực.", "Thể hiện tác phong của nhà giáo dục."]'::jsonb),
  ('OB03', '2026-10-09', 'Giới thiệu giá trị và nội quy TeenCare', 1, '["Giới thiệu các giá trị tôn trọng, cởi mở, tự tin, tử tế.", "Giải thích những nguyên tắc tương tác, đặc biệt là việc tôn trọng thông tin cá nhân.", "Cho gia đình cơ hội đặt câu hỏi hoặc trao đổi về nội quy."]'::jsonb),
  ('OB04', '2026-10-09', 'Xác nhận cam kết học tập', 1, '["Mời cả phụ huynh và học sinh tham gia xác nhận cam kết.", "Thể hiện đây là cam kết chung giữa gia đình và Mentor.", "Thực hiện hoặc hướng dẫn quy trình ký/xác nhận."]'::jsonb),
  ('OB05', '2026-10-09', 'Giới thiệu lịch trình buổi học', 1, '["Giới thiệu phần khởi động chung.", "Thông báo phần học riêng với con và nhiệm vụ dành cho phụ huynh.", "Giới thiệu phần hoạt động gia đình.", "Thông báo phần trao đổi riêng với phụ huynh."]'::jsonb),
  ('OB06', '2026-10-09', 'Thực hiện thử thách 2–3 từ khóa', 2, '["Yêu cầu phụ huynh viết 2–3 từ mô tả con.", "Yêu cầu con viết 2–3 từ mô tả phụ huynh.", "Giải thích cách thực hiện.", "Yêu cầu giữ lại câu trả lời cho phần hoạt động chung."]'::jsonb),
  ('OB07', '2026-10-09', 'Giao nhiệm vụ riêng cho phụ huynh', 2, '["Hướng dẫn phụ huynh chuyển sang không gian khác.", "Giới thiệu bài đánh giá Whole Child Assessment (WCA).", "Xác nhận phụ huynh đã nhận đúng đường dẫn.", "Giải thích mục đích bài đánh giá.", "Xác nhận con vẫn có thiết bị và không gian phù hợp để tiếp tục học riêng."]'::jsonb),
  ('OB08', '2026-10-09', 'Xác nhận không gian riêng tư và cảm xúc của con', 3, '["Xác nhận con đã sẵn sàng học riêng.", "Sử dụng câu hỏi hoặc công cụ check-in cảm xúc.", "Mời con xác định những cảm xúc hiện tại.", "Tìm hiểu thêm nguyên nhân hoặc bối cảnh của ít nhất một cảm xúc được chia sẻ.", "Ghi nhận cảm xúc mà không phán xét."]'::jsonb),
  ('OB09', '2026-10-09', 'Khám phá sở thích cá nhân', 3, '["Chia sẻ hoặc làm mẫu cách giới thiệu sở thích.", "Mời học sinh chia sẻ tối thiểu 2 sở thích.", "Hỏi thêm để hiểu điều con yêu thích.", "Không phán xét hoặc sửa đổi sở thích của con."]'::jsonb),
  ('OB10', '2026-10-09', 'Khám phá niềm tự hào về bản thân', 3, '["Hướng dẫn con nhìn lại một điều bản thân tự hào.", "Có thể dùng câu chuyện bản thân làm mẫu.", "Khuyến khích con chia sẻ những điểm tốt hoặc tiến bộ.", "Ghi nhận cụ thể phẩm chất/nỗ lực của con."]'::jsonb),
  ('OB11', '2026-10-09', 'Khám phá nỗi sợ, nỗi buồn hoặc những điều khó chia sẻ', 3, '["Tạo một hoạt động suy ngẫm về những điều khiến con lo lắng hoặc sợ hãi.", "Hướng dẫn con nhận diện cảm xúc và nguyên nhân.", "Khuyến khích con chia sẻ trong phạm vi con cảm thấy an toàn.", "Lắng nghe, ghi nhận và phản hồi có sự đồng cảm.", "Không ép buộc con tiết lộ thông tin nhạy cảm."]'::jsonb),
  ('OB12', '2026-10-09', 'Củng cố thông điệp lắng nghe và tin tưởng bản thân', 3, '["Tổng kết ý nghĩa của việc lắng nghe chính mình.", "Ghi nhận sự dũng cảm và nỗ lực của con.", "Khuyến khích con tìm kiếm sự hỗ trợ khi cần.", "Khẳng định vai trò đồng hành của Mentor."]'::jsonb),
  ('OB13', '2026-10-09', 'Giải thích sức mạnh của thói quen', 3, '["Liên hệ việc lắng nghe bản thân với chăm sóc bản thân hằng ngày.", "Sử dụng ít nhất một ví dụ gần gũi về thói quen.", "Giải thích mối liên hệ giữa hành động nhỏ lặp lại và kết quả dài hạn."]'::jsonb),
  ('OB14', '2026-10-09', 'Sử dụng câu chuyện minh họa', 3, '["Kể ít nhất một câu chuyện hoặc ví dụ về việc hình thành thói quen.", "Kết nối ví dụ với hoàn cảnh, sở thích hoặc mục tiêu của con.", "Giải thích bài học rút ra."]'::jsonb),
  ('OB15', '2026-10-09', 'Xác định mục tiêu cá nhân', 3, '["Hỏi con về mục tiêu dài hạn, chẳng hạn điều con mong muốn khi 18 tuổi.", "Hỏi về mục tiêu ngắn hạn.", "Ghi nhận nguyện vọng.", "Giúp con nhận ra việc đạt mục tiêu cần thời gian, sự rèn luyện và hỗ trợ."]'::jsonb),
  ('OB16', '2026-10-09', 'Kết nối với định hướng Thân – Tâm – Trí', 3, '["Giải thích định hướng phát triển toàn diện tại TeenCare.", "Liên hệ thể chất khỏe mạnh, tâm hồn bình an và trí tuệ với những mục tiêu của con.", "Đảm bảo nội dung được diễn đạt dễ hiểu theo lứa tuổi."]'::jsonb),
  ('OB17', '2026-10-09', 'Xây dựng sự sẵn sàng tham gia học tập', 3, '["Hỏi con về mong muốn tiếp tục tham gia.", "Giúp con hiểu những hoạt động sắp tới", "Khuyến khích con thể hiện sự chủ động.", "Không thay thế câu trả lời của con bằng suy đoán của Mentor."]'::jsonb),
  ('OB18', '2026-10-09', 'Thống nhất lịch học ba lớp', 3, '["Giới thiệu lịch Mentor 1:1.", "Giới thiệu lịch Kỹ năng sống.", "Giới thiệu lịch Thể chất.", "Kiểm tra lịch có phù hợp và trùng với hoạt động khác không.", "Hướng dẫn con ghi lại thời khóa biểu."]'::jsonb),
  ('OB19', '2026-10-09', 'Giao thử thách hình thành thói quen', 3, '["Giới thiệu thử thách cụ thể cho giai đoạn đầu.", "Cho con lựa chọn hoạt động phù hợp, như dọn giường hoặc tập thể dục.", "Xác định khi nào thực hiện.", "Hướng dẫn cách báo cáo kết quả.", "Ghi nhận sự sẵn sàng của con."]'::jsonb),
  ('OB20', '2026-10-09', 'Chuẩn bị chuyển tiếp sang phần gia đình', 3, '["Nhắc lại ý nghĩa của sự kiên trì và đồng hành.", "Khuyến khích con chia sẻ suy nghĩ về việc tiếp tục học khi gặp khó khăn.", "Xem lại các từ khóa con đã viết về phụ huynh.", "Chuẩn bị không khí phù hợp trước khi mời phụ huynh quay lại."]'::jsonb),
  ('OB21', '2026-10-09', 'Tóm tắt kết quả buổi học riêng', 4, '["Chào đón phụ huynh quay lại.", "Tóm tắt các nội dung con đã học: lắng nghe bản thân, thói quen và mục tiêu cá nhân.", "Chia sẻ những điểm tích cực quan sát được ở con.", "Tôn trọng thông tin riêng tư con đã chia sẻ."]'::jsonb),
  ('OB22', '2026-10-09', 'Củng cố tinh thần đồng hành và nội quy', 4, '["Nhắc lại ý nghĩa của việc kiên trì.", "Mời cả phụ huynh và con thể hiện quan điểm về hành trình học.", "Nhắc lại thử thách của con và cách phụ huynh hỗ trợ.", "Giải thích những yêu cầu tham gia các lớp học."]'::jsonb),
  ('OB23', '2026-10-09', 'Giới thiệu vai trò và tạo không khí', 4, '["Giới thiệu con là \"Chim sẻ\" và phụ huynh là \"Đại bàng\".", "Giải thích hoạt động.", "Hướng dẫn tương tác khởi động.", "Tạo không khí ấm áp, cởi mở."]'::jsonb),
  ('OB24', '2026-10-09', 'Hoạt động nhìn lại ký ức và chia sẻ từ khóa', 4, '["Mời hai người dành thời gian chú ý đến nhau.", "Gợi nhớ những kỷ niệm chung.", "Sử dụng lại các từ khóa đã viết ở hoạt động khởi động.", "Tạo cơ hội để mỗi người chia sẻ về người còn lại.", "Khuyến khích phản hồi bằng sự ghi nhận."]'::jsonb),
  ('OB25', '2026-10-09', 'Hoạt động chia sẻ cảm xúc khó nói', 4, '["Hướng dẫn hai người nhớ lại những thời điểm khó khăn hoặc cảm xúc chưa được nói ra.", "Mời mỗi người chia sẻ nếu cảm thấy thoải mái.", "Khuyến khích người nghe ghi nhận thay vì tranh luận, phòng thủ hoặc phán xét.", "Tôn trọng quyền từ chối các tương tác thân thể hoặc chia sẻ riêng tư."]'::jsonb),
  ('OB26', '2026-10-09', 'Hoạt động ghi nhận và cảm ơn', 4, '["Hướng dẫn hai người nhớ lại những kỷ niệm tích cực.", "Mời phụ huynh gửi lời cảm ơn tới con.", "Mời con gửi lời cảm ơn tới phụ huynh.", "Tổng kết ý nghĩa của việc lắng nghe và ghi nhận."]'::jsonb),
  ('OB27', '2026-10-09', 'Check-out cảm xúc và kết thúc hoạt động', 4, '["Hỏi cảm xúc của con sau hoạt động.", "Hỏi cảm xúc của phụ huynh.", "Ghi nhận phản hồi của cả hai.", "Kết thúc phần gia đình bằng sự tôn trọng và cảm ơn.", "Hướng dẫn con rời buổi học trước khi bắt đầu trao đổi riêng."]'::jsonb),
  ('OB28', '2026-10-09', 'Nhắc lại nội dung buổi khai giảng', 5, '["Hỏi phụ huynh về trải nghiệm tại buổi khai giảng.", "Xác định phụ huynh đã tham gia hoặc nhớ những nội dung nào.", "Kết nối với các triết lý giáo dục được đề cập trong script:", "Hiểu con trước khi lựa chọn cách tiếp cận.", "Giải quyết nguyên nhân gốc thay vì chỉ tập trung vào biểu hiện.", "Thay đổi bền vững cần sự thực hành và kiên trì."]'::jsonb),
  ('OB29', '2026-10-09', 'Khai thác lý do gia đình lựa chọn TeenCare', 5, '["Hỏi phụ huynh vì sao lựa chọn TeenCare.", "Tìm hiểu kỳ vọng của gia đình.", "Khai thác những khó khăn, biểu hiện và thời gian xuất hiện.", "Tìm hiểu những phương pháp gia đình từng thử.", "Lắng nghe và tóm tắt lại các vấn đề chính."]'::jsonb),
  ('OB30', '2026-10-09', 'Đưa ra nhận định sư phạm về học sinh', 5, '["Bắt đầu từ những điểm mạnh hoặc tiến bộ quan sát được.", "Nêu những điểm con cần được hỗ trợ.", "Sử dụng bằng chứng cụ thể từ hoạt động thực tế hoặc thông tin phụ huynh đã chia sẻ.", "Phân biệt quan sát với suy luận.", "Giải thích ý nghĩa giáo dục và những hướng hỗ trợ phù hợp."]'::jsonb),
  ('OB31', '2026-10-09', 'Khai thác kết quả WCA và nhu cầu xây dựng thói quen', 5, '["Xác nhận tình trạng hoàn thành WCA.", "Nếu có kết quả, sử dụng dữ liệu phù hợp để trao đổi.", "Hỏi phụ huynh về điều đã nhận ra sau khi làm bài.", "Thảo luận về mục tiêu thay đổi hành vi, thói quen và thời gian cần thiết.", "Tìm hiểu sự khác biệt giữa kỳ vọng và tình trạng hiện tại."]'::jsonb),
  ('OB32', '2026-10-09', 'Giới thiệu mô hình TeenCare', 5, '["Giới thiệu các thành phần liên quan trong hệ sinh thái.", "Giải thích vai trò của Mentor 1:1, lớp Kỹ năng sống, hoạt động Thể chất và công nghệ giáo dục.", "Liên hệ giải pháp với nhu cầu đã xác định."]'::jsonb),
  ('OB33', '2026-10-09', 'So sánh các chương trình Học tập và Huấn luyện', 5, '["Giải thích điểm chung giữa các chương trình.", "Làm rõ khác biệt về mục tiêu đầu ra.", "So sánh tần suất Mentor 1:1 và nội dung học tập.", "Giải thích vai trò huấn luyện thói quen và sự đồng hành của phụ huynh.", "Hỏi phụ huynh chương trình nào phù hợp với nhu cầu gia đình."]'::jsonb),
  ('OB34', '2026-10-09', 'Giải thích chi phí và điều kiện đăng ký', 5, '["Nêu giá và quyền lợi theo chính sách hiện hành.", "Giải thích thời gian chương trình.", "Làm rõ tổng số tiền, phương thức thanh toán và các điều kiện liên quan.", "Giải thích ưu đãi khi thực sự áp dụng.", "Kiểm tra xem phụ huynh còn câu hỏi nào không."]'::jsonb),
  ('OB35', '2026-10-09', 'Lắng nghe và giải quyết băn khoăn', 5, '["Hỏi phụ huynh có băn khoăn nào chưa được giải đáp.", "Xác định đúng nguyên nhân băn khoăn: hiệu quả, thời gian, khả năng tham gia của con, tài chính hoặc lý do khác.", "Phản hồi bằng thông tin chính xác và liên hệ với nhu cầu gia đình.", "Không tự giả định phụ huynh đã đồng ý.", "Tôn trọng quyền cân nhắc và quyết định."]'::jsonb),
  ('OB36', '2026-10-09', 'Xác nhận lựa chọn và bước tiếp theo', 5, '["Hỏi rõ quyết định hoặc mong muốn tiếp theo của phụ huynh.", "Nếu đồng ý đăng ký, giải thích các thủ tục cần thực hiện.", "Nếu chưa quyết định, thống nhất bước tiếp theo nếu phụ huynh mong muốn.", "Tóm tắt các nội dung đã thống nhất."]'::jsonb),
  ('OB37', '2026-10-09', 'Hướng dẫn phụ huynh đồng hành cùng con', 5, '["Nhắc lại thử thách đã giao cho con.", "Giải thích cách phụ huynh hỗ trợ.", "Hướng dẫn sử dụng ứng dụng hoặc các tài nguyên liên quan nếu phù hợp.", "Nhắc lại lịch học và kênh liên lạc.", "Cảm ơn và kết thúc buổi gặp chuyên nghiệp."]'::jsonb)
